  1	// src/lib/rechner/solarpark.js
  2	//
  3	// Renditerechnung eines Solarparks über die gesamte Laufzeit – reine Logik
  4	// ohne React, damit Rechner, Hub-Vorschau und Selbsttest dieselben Zahlen
  5	// liefern. Alle Standardwerte kommen aus src/lib/invest/markt.js.
  6	//
  7	// Methodik (bewusst einfach und offen gelegt):
  8	//  - Jahreswerte, Jahr 0 = Investition, Jahr 1 … Laufzeit = Betrieb
  9	//  - Erzeugung: Regionsertrag × Bauartfaktor, jährliche Degradation
 10	//  - Erlöse: Vertragsphase und danach Marktwert (Merchant, heutiger Preis,
 11	//    fortgeschrieben mit der Marktwert-Steigerung). EEG-Zuschlag wirkt im
 12	//    Marktprämienmodell als Untergrenze: Liegt der Marktwert darüber, bleibt
 13	//    der Marktwert. Ein PPA ist ein nominal fester Preis.
 14	//  - Kosten: Betriebskosten + Pacht (beide mit Inflation), Rückbau-Rücklage
 15	//  - Finanzierung: Annuitätendarlehen über die Tilgungsdauer; optional wird
 16	//    das Darlehen wie bei Banken üblich auf eine Mindest-DSCR begrenzt
 17	//  - Renditen vor Steuern (Projekt- und Eigenkapital-IRR)
 18	//  - LCOE nominal: konstanter Strompreis, bei dem der Kapitalwert zum WACC null ist
 19	
 20	import { FREIFLAECHE, ERLOESE, FINANZIERUNG, PACHT, BAUART, regionById, npv, irr, annuitaet } from "../invest/markt.js";
 21	
 22	export const ERLOESMODELLE = {
 23	  eeg: { label: "EEG-Zuschlag", kurz: "EEG", vertragJahre: 20, preisCt: ERLOESE.eegFreiflaecheCt },
 24	  ppa: { label: "PPA", kurz: "PPA", vertragJahre: 10, preisCt: ERLOESE.ppaCt.mittel },
 25	  merchant: { label: "Merchant", kurz: "Markt", vertragJahre: 0, preisCt: ERLOESE.merchantCt },
 26	};
 27	
 28	export const STANDARD = {
 29	  mwp: 10,
 30	  regionId: "de-sued",
 31	  bauart: "sued",
 32	  capexKwp: FREIFLAECHE.capexProKwp.mittel,
 33	  entwicklungKwp: FREIFLAECHE.entwicklungProKwp.min,
 34	  netzKm: 1,
 35	  modell: "eeg",
 36	  preisCt: ERLOESE.eegFreiflaecheCt,
 37	  vertragJahre: 20,
 38	  merchantCt: ERLOESE.merchantCt,
 39	  merchantSteigerung: ERLOESE.merchantSteigerung,
 40	  pachtHa: PACHT.freiflaecheProHa.mittel,
 41	  opexKwp: FREIFLAECHE.opexProKwp,
 42	  degradation: FREIFLAECHE.degradation,
 43	  fkQuote: FINANZIERUNG.fremdkapitalQuote,
 44	  zins: FINANZIERUNG.zins,
 45	  tilgungJahre: FINANZIERUNG.tilgungJahre,
 46	  laufzeit: FREIFLAECHE.laufzeit,
 47	  inflation: FREIFLAECHE.inflation,
 48	  ekRendite: FINANZIERUNG.diskont,
 49	  /** Darlehen auf Mindest-DSCR begrenzen (Bankpraxis) */
 50	  dscrBegrenzen: true,
 51	  dscrZiel: FINANZIERUNG.dscrZiel,
 52	};
 53	
 54	/** Investitionsbausteine in € */
 55	export function investition({ mwp, capexKwp, entwicklungKwp = 0, netzKm = 0 }) {
 56	  const kwp = mwp * 1000;
 57	  const anlage = kwp * capexKwp;
 58	  const netz = mwp * FREIFLAECHE.netzanschlussFixProMwp + netzKm * 1000 * FREIFLAECHE.kabelProMeter;
 59	  const entwicklung = kwp * entwicklungKwp;
 60	  return { anlage, netz, entwicklung, summe: anlage + netz + entwicklung };
 61	}
 62	
 63	/**
 64	 * Hauptrechnung. Alle Parameter optional (Standard aus STANDARD).
 65	 * Preise in ct/kWh, Quoten als Anteil (0,75), Zins als Anteil (0,045).
 66	 */
 67	export function rechneSolarpark(eingabe = {}) {
 68	  const e = { ...STANDARD, ...eingabe };
 69	  const kwp = e.mwp * 1000;
 70	  const region = regionById(e.regionId);
 71	  const bauart = BAUART[e.bauart] || BAUART.sued;
 72	  // Optional: spezifischer Ertrag aus einem Ertragsgutachten (z. B. P50/P90 aus dem Projektdatenblatt der Börse)
 73	  const spezErtrag = e.spezErtrag > 0 ? e.spezErtrag : region.ertrag * bauart.faktor;
 74	  const flaecheHa = e.mwp * bauart.haProMwp;
 75	  const inv = investition(e);
 76	  const vertragJahre = e.modell === "merchant" ? 0 : Math.min(e.vertragJahre, e.laufzeit);
 77	
 78	  // Erzeugung und operativer Cashflow (unabhängig von der Finanzierung)
 79	  const betrieb = [];
 80	  for (let t = 1; t <= e.laufzeit; t++) {
 81	    const erzeugung = kwp * spezErtrag * Math.pow(1 - e.degradation, t - 1); // kWh
 82	    const indexiert = Math.pow(1 + e.inflation, t - 1);
 83	    const marktCt = e.merchantCt * Math.pow(1 + e.merchantSteigerung, t - 1);
 84	    const imVertrag = t <= vertragJahre;
 85	    const preisCt = !imVertrag ? marktCt : e.modell === "eeg" ? Math.max(e.preisCt, marktCt) : e.preisCt;
 86	    const erloes = (erzeugung * preisCt) / 100;
 87	    const opex = kwp * e.opexKwp * indexiert;
 88	    const pacht = flaecheHa * e.pachtHa * Math.pow(1 + PACHT.indexierung, t - 1);
 89	    const rueckbau = (kwp * FREIFLAECHE.rueckbauProKwp) / e.laufzeit;
 90	    const kosten = opex + pacht + rueckbau;
 91	    betrieb.push({ jahr: t, erzeugung, preisCt, marktCt, imVertrag, erloes, opex, pacht, rueckbau, kosten, ebitda: erloes - kosten });
 92	  }
 93	
 94	  // Fremdkapital: gewünschte Quote, ggf. begrenzt durch die Mindest-DSCR
 95	  const tilgungJahre = Math.min(e.tilgungJahre, e.laufzeit);
 96	  const fkWunsch = inv.summe * e.fkQuote;
 97	  const faktor = annuitaet(1, e.zins, tilgungJahre); // Rate je 1 € Darlehen
 98	  const minCfads = Math.min(...betrieb.slice(0, tilgungJahre).map((b) => b.ebitda));
 99	  const fkMax = minCfads > 0 ? minCfads / e.dscrZiel / faktor : 0;
100	  const fkBegrenzt = e.dscrBegrenzen && fkWunsch > fkMax;
101	  const fk = fkBegrenzt ? fkMax : fkWunsch;
102	  const fkQuoteEff = inv.summe > 0 ? fk / inv.summe : 0;
103	  const ek = inv.summe - fk;
104	  const rate = fk > 0 ? fk * faktor : 0;
105	  // Kapitalkosten für Barwert und LCOE aus der Zielstruktur (unabhängig davon,
106	  // ob die Bank das Darlehen kürzt) – so bleibt die LCOE vom Erlös unabhängig.
107	  const wacc = e.fkQuote * e.zins + (1 - e.fkQuote) * e.ekRendite;
108	
109	  const jahre = [];
110	  let restschuld = fk;
111	  for (const b of betrieb) {
112	    const t = b.jahr;
113	    const { ebitda } = b;
114	    let zinsen = 0;
115	    let tilgung = 0;
116	    if (restschuld > 0.5 && t <= tilgungJahre) {
117	      zinsen = restschuld * e.zins;
118	      tilgung = Math.min(rate - zinsen, restschuld);
119	      restschuld -= tilgung;
120	    }
121	    const schuldendienst = zinsen + tilgung;
122	    jahre.push({
123	      ...b,
124	      zinsen,
125	      tilgung,
126	      schuldendienst,
127	      cfProjekt: ebitda,
128	      cfEk: ebitda - schuldendienst,
129	      dscr: schuldendienst > 0 ? ebitda / schuldendienst : null,
130	      restschuld: Math.max(restschuld, 0),
131	    });
132	  }
133	
134	  const cfProjekt = [-inv.summe, ...jahre.map((j) => j.cfProjekt)];
135	  const cfEk = [-ek, ...jahre.map((j) => j.cfEk)];
136	  const projektIrr = irr(cfProjekt);
137	  const ekIrr = ek > 0 ? irr(cfEk) : null;
138	  const kapitalwert = npv(wacc, cfProjekt);
139	  const kapitalwertEk = npv(e.ekRendite, cfEk);
140	
141	  // LCOE nominal: Barwert Kosten / Barwert Erzeugung (Diskont = WACC)
142	  const bwKosten = inv.summe + jahre.reduce((s, j) => s + j.kosten / Math.pow(1 + wacc, j.jahr), 0);
143	  const bwEnergie = jahre.reduce((s, j) => s + j.erzeugung / Math.pow(1 + wacc, j.jahr), 0);
144	  const lcoeCt = (bwKosten / bwEnergie) * 100;
145	
146	  // Amortisation (Projekt, statisch-kumuliert, mit linearer Interpolation)
147	  let kum = -inv.summe;
148	  let amortisation = null;
149	  for (const j of jahre) {
150	    const vorher = kum;
151	    kum += j.cfProjekt;
152	    if (amortisation == null && kum >= 0) amortisation = j.jahr - 1 + (-vorher / j.cfProjekt);
153	  }
154	  let kumEk = -ek;
155	  let amortisationEk = null;
156	  for (const j of jahre) {
157	    const vorher = kumEk;
158	    kumEk += j.cfEk;
159	    if (amortisationEk == null && kumEk >= 0 && j.cfEk > 0) amortisationEk = j.jahr - 1 + (-vorher / j.cfEk);
160	  }
161	
162	  const mitDienst = jahre.filter((j) => j.dscr != null);
163	  const dscrMin = mitDienst.length ? Math.min(...mitDienst.map((j) => j.dscr)) : null;
164	  const dscrMittel = mitDienst.length ? mitDienst.reduce((s, j) => s + j.dscr, 0) / mitDienst.length : null;
165	
166	  const summe = (k) => jahre.reduce((s, j) => s + j[k], 0);
167	
168	  return {
169	    eingabe: e,
170	    kwp,
171	    region,
172	    bauart,
173	    spezErtrag,
174	    flaecheHa,
175	    ertragJahr1: jahre[0]?.erzeugung || 0,
176	    investition: inv,
177	    investProKwp: inv.summe / kwp,
178	    fk,
179	    fkWunsch,
180	    fkQuoteEff,
181	    fkBegrenzt,
182	    ek,
183	    rate,
184	    wacc,
185	    vertragJahre,
186	    jahre,
187	    projektIrr,
188	    ekIrr,
189	    kapitalwert,
190	    kapitalwertEk,
191	    lcoeCt,
192	    amortisation,
193	    amortisationEk,
194	    dscrMin,
195	    dscrMittel,
196	    summen: { erloes: summe("erloes"), kosten: summe("kosten"), schuldendienst: summe("schuldendienst"), cfEk: summe("cfEk"), erzeugung: summe("erzeugung") },
197	  };
198	}
199	
200	/**
201	 * Sensitivität: Projekt- und EK-IRR bei veränderten Investitionskosten
202	 * (Zeilen) und Strompreisen (Spalten, wirkt auf Vertrags- und Marktpreis).
203	 */
204	export function sensitivitaet(eingabe = {}, schritteCapex = [-0.1, -0.05, 0, 0.05, 0.1], schrittePreis = [-0.1, -0.05, 0, 0.05, 0.1]) {
205	  const e = { ...STANDARD, ...eingabe };
206	  return schritteCapex.map((dc) => ({
207	    capex: dc,
208	    capexKwp: e.capexKwp * (1 + dc),
209	    zellen: schrittePreis.map((dp) => {
210	      const r = rechneSolarpark({ ...e, capexKwp: e.capexKwp * (1 + dc), preisCt: e.preisCt * (1 + dp), merchantCt: e.merchantCt * (1 + dp) });
211	      return { preis: dp, projektIrr: r.projektIrr, ekIrr: r.ekIrr, dscrMin: r.dscrMin };
212	    }),
213	  }));
214	}
215	
216	/* ------------------------------------------------------------------ */
217	/* Selbsttest: node src/lib/rechner/solarpark.js                       */
218	/* ------------------------------------------------------------------ */
219	
220	export function selbsttest() {
221	  const fehler = [];
222	  const pruefe = (ok, text) => {
223	    if (!ok) fehler.push(text);
224	  };
225	
226	  const r = rechneSolarpark({ mwp: 10, regionId: "de-sued", bauart: "sued", capexKwp: 530, modell: "eeg", preisCt: 5, vertragJahre: 20 });
227	  pruefe(r.kwp === 10000, "10 MWp = 10.000 kWp");
228	  pruefe(Math.abs(r.ertragJahr1 - 11_000_000) < 1, "Ertrag Jahr 1: 10.000 kWp × 1.100 kWh/kWp = 11 GWh");
229	  pruefe(r.lcoeCt > 4.5 && r.lcoeCt < 6.5, `LCOE plausibel 4,5–6,5 ct (ist ${r.lcoeCt.toFixed(2)})`);
230	  pruefe(r.projektIrr > 0.02 && r.projektIrr < 0.09, `Projekt-IRR plausibel 2–9 % (ist ${(r.projektIrr * 100).toFixed(2)} %)`);
231	  pruefe(r.jahre.length === 30, "30 Betriebsjahre");
232	  pruefe(r.jahre[19].imVertrag && !r.jahre[20].imVertrag, "EEG endet nach Jahr 20");
233	  pruefe(Math.abs(r.jahre[r.eingabe.tilgungJahre - 1].restschuld) < 1, "Darlehen am Ende der Tilgungsdauer getilgt");
234	  pruefe(r.jahre[r.eingabe.tilgungJahre].schuldendienst === 0, "nach Tilgung kein Schuldendienst");
235	  pruefe(Math.abs(r.fk + r.ek - r.investition.summe) < 1, "FK + EK = Investition");
236	
237	  const teurer = rechneSolarpark({ mwp: 10, capexKwp: 600, preisCt: 5 });
238	  pruefe(teurer.projektIrr < r.projektIrr, "höhere Capex senken den IRR");
239	  const besser = rechneSolarpark({ mwp: 10, capexKwp: 530, preisCt: 6 });
240	  pruefe(besser.projektIrr > r.projektIrr, "höherer Preis erhöht den IRR");
241	  pruefe(Math.abs(besser.lcoeCt - r.lcoeCt) < 1e-9, "LCOE unabhängig vom Erlös");
242	  pruefe(r.dscrMin >= r.eingabe.dscrZiel - 1e-6, "Darlehen auf Mindest-DSCR begrenzt");
243	  const frei = rechneSolarpark({ mwp: 10, capexKwp: 530, preisCt: 5, dscrBegrenzen: false });
244	  pruefe(Math.abs(frei.fkQuoteEff - 0.75) < 1e-9, "ohne Begrenzung gilt die gewünschte FK-Quote");
245	  const eegBoden = rechneSolarpark({ mwp: 10, preisCt: 3, merchantCt: 5, merchantSteigerung: 0 });
246	  pruefe(Math.abs(eegBoden.jahre[0].preisCt - 5) < 1e-9, "EEG wirkt als Untergrenze: höherer Marktwert bleibt");
247	  const ppaFest = rechneSolarpark({ mwp: 10, modell: "ppa", preisCt: 3, vertragJahre: 10, merchantCt: 5, merchantSteigerung: 0 });
248	  pruefe(Math.abs(ppaFest.jahre[0].preisCt - 3) < 1e-9 && Math.abs(ppaFest.jahre[10].preisCt - 5) < 1e-9, "PPA fest, danach Marktwert");
249	
250	  const ohneFk = rechneSolarpark({ mwp: 10, capexKwp: 530, preisCt: 5, fkQuote: 0 });
251	  pruefe(Math.abs(ohneFk.ekIrr - ohneFk.projektIrr) < 1e-4, "ohne Fremdkapital: EK-IRR = Projekt-IRR");
252	  pruefe(ohneFk.dscrMin == null, "ohne Fremdkapital kein DSCR");
253	
254	  const lcoePreis = rechneSolarpark({ mwp: 10, capexKwp: 530, preisCt: 5, modell: "ppa", vertragJahre: 30 });
255	  const lcoeFall = rechneSolarpark({ mwp: 10, capexKwp: 530, modell: "ppa", preisCt: lcoePreis.lcoeCt, vertragJahre: 30 });
256	  pruefe(Math.abs(lcoeFall.projektIrr - lcoeFall.wacc) < 0.001, "Preis = LCOE über die ganze Laufzeit → Projekt-IRR = WACC");
257	
258	  const m = sensitivitaet({ mwp: 10, capexKwp: 530, preisCt: 5 });
259	  pruefe(m.length === 5 && m[0].zellen.length === 5, "Sensitivitätsmatrix 5 × 5");
260	  pruefe(m[0].zellen[4].projektIrr > m[4].zellen[0].projektIrr, "günstig + teurer Strom schlägt teuer + billiger Strom");
261	
262	  return { fehler, beispiel: r };
263	}
264	
265	if (typeof process !== "undefined" && process.argv?.[1] && /solarpark\.js$/.test(process.argv[1].replace(/\\/g, "/"))) {
266	  const { fehler, beispiel: r } = selbsttest();
267	  const p = (x) => (x == null ? "–" : `${(x * 100).toFixed(2)} %`);
268	  console.log(
269	    `Beispiel 10 MWp Süd, 530 €/kWp, EEG 5 ct: Invest ${Math.round(r.investProKwp)} €/kWp, LCOE ${r.lcoeCt.toFixed(2)} ct, ` +
270	      `Projekt-IRR ${p(r.projektIrr)}, EK-IRR ${p(r.ekIrr)}, DSCR min ${r.dscrMin?.toFixed(2)}, Amortisation ${r.amortisation?.toFixed(1)} J., WACC ${p(r.wacc)}`
271	  );
272	  if (fehler.length) {
273	    console.error("FEHLER:\n- " + fehler.join("\n- "));
274	    process.exit(1);
275	  }
276	  console.log("Selbsttest solarpark.js: alle Prüfungen bestanden.");
277	}

  1	// src/lib/rechner/flaechencheck.js
  2	//
  3	// Flächencheck: erste Eignungseinschätzung einer Fläche für Freiflächen-PV.
  4	// Reine Funktion ohne React – testbar mit Node. Marktwerte aus markt.js,
  5	// die Punktelogik ist eine bewusst einfache, transparente Heuristik.
  6	
  7	import { AGRI, BAUART, FREIFLAECHE, PACHT, REGIONEN, regionById } from "../invest/markt.js";
  8	
  9	export const LAENDER = [
 10	  { id: "DE", label: "Deutschland" },
 11	  { id: "AT", label: "Österreich" },
 12	  { id: "CH", label: "Schweiz" },
 13	];
 14	
 15	export const regionenFuer = (land) => REGIONEN.filter((r) => r.land === land);
 16	
 17	export const NUTZUNGEN = [
 18	  { id: "acker", label: "Acker", text: "Ackerland in Bewirtschaftung" },
 19	  { id: "gruenland", label: "Grünland", text: "Wiese, Weide, Dauergrünland" },
 20	  { id: "konversion", label: "Konversion", text: "Ehem. Militär, Gewerbe, Bahn, Abbau" },
 21	  { id: "deponie", label: "Deponie", text: "Abgedeckte Deponie, Halde" },
 22	  { id: "parkplatz", label: "Parkplatz", text: "Versiegelte Stellfläche" },
 23	  { id: "sonstige", label: "Sonstige", text: "Brache, Mischnutzung, unklar" },
 24	];
 25	
 26	export const BESONDERHEITEN = [
 27	  { id: "randstreifen", label: "Randstreifen Autobahn/Schiene", text: "Bis 500 m neben Autobahn oder Schienenweg" },
 28	  { id: "benachteiligt", label: "Benachteiligtes Gebiet", text: "Landwirtschaftlich benachteiligte Gebietskulisse" },
 29	  { id: "schutzgebiet", label: "Schutzgebiet", text: "Naturschutz-, FFH-, Vogelschutz- oder Wasserschutzgebiet" },
 30	  { id: "wald", label: "Wald angrenzend", text: "Waldrand direkt an der Fläche" },
 31	  { id: "hang", label: "Hangneigung", text: "Deutlich geneigt, vor allem nach Norden" },
 32	  { id: "ueberschwemmung", label: "Überschwemmungsgebiet", text: "Festgesetztes Überschwemmungsgebiet" },
 33	];
 34	
 35	export const NETZ = [
 36	  { id: "lt1", label: "unter 1 km", km: 0.7 },
 37	  { id: "1-3", label: "1–3 km", km: 2 },
 38	  { id: "3-5", label: "3–5 km", km: 4 },
 39	  { id: "5-10", label: "5–10 km", km: 7.5 },
 40	  { id: "gt10", label: "über 10 km", km: 12 },
 41	  { id: "unbekannt", label: "weiß ich nicht", km: null },
 42	];
 43	
 44	export const EIGENTUM = [
 45	  { id: "allein", label: "Alleineigentum", text: "Ich entscheide allein" },
 46	  { id: "gemeinschaft", label: "Mehrere Eigentümer", text: "Ehepaar, Erbengemeinschaft, GbR" },
 47	  { id: "verpachtet", label: "Derzeit verpachtet", text: "Ein Landwirt bewirtschaftet die Fläche" },
 48	  { id: "kommune", label: "Kommune / Kirche / Verband", text: "Gremienbeschluss nötig" },
 49	];
 50	
 51	const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
 52	
 53	/**
 54	 * Bewertet eine Fläche.
 55	 * eingaben: { land, regionId, ha, nutzung, besonderheiten: [], netz, eigentum }
 56	 */
 57	export function flaechencheck({ land = "DE", regionId, ha = 10, nutzung = "acker", besonderheiten = [], netz = "unbekannt", eigentum = "allein" } = {}) {
 58	  const region = regionById(regionId || regionenFuer(land)[0]?.id);
 59	  const hat = (id) => besonderheiten.includes(id);
 60	  const gruende = []; // { punkte, text, art: plus|minus|info }
 61	  const add = (punkte, text, art) => gruende.push({ punkte, text, art: art || (punkte > 0 ? "plus" : punkte < 0 ? "minus" : "info") });
 62	  let punkte = 50;
 63	  let deckel = 100;
 64	
 65	  // --- Größe -------------------------------------------------------
 66	  if (ha < 1) {
 67	    add(-30, "Unter 1 ha ist ein eigener Solarpark kaum wirtschaftlich – eher Agri-PV am Hof, Carport oder Anschluss an eine Nachbarfläche.");
 68	    deckel = 35;
 69	  } else if (ha < FREIFLAECHE.mindestHa) {
 70	    add(-10, `Unter ${FREIFLAECHE.mindestHa} ha wird es knapp; mit Nachbarflächen oder als Agri-PV kann es passen.`);
 71	  } else if (ha < 5) {
 72	    add(5, "Die Größe reicht für einen kleineren Solarpark.");
 73	  } else if (ha <= 100) {
 74	    add(ha >= 20 ? 20 : 15, "Gute Größe: Fixkosten für Planung und Netzanschluss verteilen sich auf viel Leistung.");
 75	  } else {
 76	    add(12, "Sehr große Fläche – attraktiv, aber Netzkapazität und Genehmigung werden zum Engpass; ggf. in Abschnitten.");
 77	  }
 78	
 79	  // --- Nutzung -----------------------------------------------------
 80	  const nutzungText = {
 81	    acker: [5, "Ackerland ist meist eben und gut erschlossen. Gemeinden achten auf Bodenqualität – Agri-PV kann eine Alternative sein."],
 82	    gruenland: [0, "Grünland ist möglich; bei Dauergrünland gelten teils Umbruch- und Naturschutzauflagen."],
 83	    konversion: [15, "Konversionsflächen sind politisch erwünscht und in Deutschland EEG-förderfähig."],
 84	    deponie: [8, "Deponien sind geeignet, brauchen aber Ballast- statt Rammfundamente und Abstimmung mit der Abfallbehörde."],
 85	    parkplatz: [0, "Auf Parkplätzen wird statt eines Solarparks ein Solarcarport gebaut – eigenes Modell, gern prüfen wir beides."],
 86	    sonstige: [0, "Die Nutzung klären wir im Gespräch – Brachen sind oft gut geeignet."],
 87	  }[nutzung] || [0, ""];
 88	  if (nutzungText[1]) add(nutzungText[0], nutzungText[1]);
 89	
 90	  // --- Besonderheiten ---------------------------------------------
 91	  if (hat("randstreifen")) {
 92	    add(15, land === "DE"
 93	      ? "Randstreifen an Autobahn/Schiene: EEG-Flächenkulisse (bis 500 m); bis 200 m ist die Anlage im Außenbereich baurechtlich privilegiert."
 94	      : "Flächen entlang von Verkehrswegen gelten auch in AT/CH als vorbelastet und sind raumplanerisch oft bevorzugt.");
 95	  }
 96	  if (hat("benachteiligt")) {
 97	    if (land === "DE") add(8, "Benachteiligtes Gebiet: Acker- und Grünland ist dort grundsätzlich EEG-förderfähig, sofern das Land nicht ausgeschlossen hat.");
 98	    else add(0, "Benachteiligte Gebiete spielen in AT/CH für die Förderung keine eigene Rolle.", "info");
 99	  }
100	  if (hat("schutzgebiet")) {
101	    add(-30, "Schutzgebiet: Naturschutz-, FFH- und Wasserschutzgebiete schließen einen Solarpark meist aus; Landschaftsschutzgebiete im Einzelfall möglich.");
102	    deckel = Math.min(deckel, 45);
103	  }
104	  if (hat("wald")) add(-8, "Waldrand: Abstand, Verschattung und Brandschutz kosten nutzbare Fläche.");
105	  if (hat("hang")) add(-10, "Hangneigung: Süd- und leichte Ost/West-Hänge gehen gut, steile Nordhänge kaum.");
106	  if (hat("ueberschwemmung")) {
107	    add(-20, "Überschwemmungsgebiet: nur mit wasserrechtlicher Ausnahme und erhöhter Aufständerung.");
108	    deckel = Math.min(deckel, 55);
109	  }
110	
111	  // --- Netzanschluss ----------------------------------------------
112	  const nutzbarHa = ha * (hat("wald") ? 0.92 : 1) * (hat("hang") ? 0.95 : 1);
113	  const kwp = (nutzbarHa / FREIFLAECHE.haProMwp) * 1000;
114	  const netzInfo = NETZ.find((n) => n.id === netz) || NETZ[NETZ.length - 1];
115	  let netzProKwp = null;
116	  if (netzInfo.km == null) {
117	    add(0, "Entfernung zum Netz unbekannt – wir fragen die Anschlusskapazität beim Netzbetreiber an.", "info");
118	  } else {
119	    netzProKwp = (netzInfo.km * 1000 * FREIFLAECHE.kabelProMeter + (kwp / 1000) * FREIFLAECHE.netzanschlussFixProMwp) / Math.max(kwp, 1);
120	    if (netzProKwp < 70) add(15, `Netzanschluss nah: rund ${Math.round(netzProKwp)} €/kWp für Kabeltrasse und Übergabestation.`);
121	    else if (netzProKwp < 110) add(5, `Netzanschluss tragbar: rund ${Math.round(netzProKwp)} €/kWp.`);
122	    else if (netzProKwp < 200) add(-8, `Netzanschluss teuer: rund ${Math.round(netzProKwp)} €/kWp – erst ab mehr Fläche gut tragbar.`);
123	    else add(-20, `Netzanschluss sehr teuer: rund ${Math.round(netzProKwp)} €/kWp. Mit Nachbarflächen oder Speicher neu rechnen.`);
124	  }
125	
126	  // --- Eigentum ----------------------------------------------------
127	  const eig = {
128	    allein: [5, "Alleineigentum: kurze Wege bis zur Unterschrift."],
129	    gemeinschaft: [0, "Mehrere Eigentümer: Alle müssen zustimmen – wir helfen bei der Abstimmung."],
130	    verpachtet: [-3, "Bestehender Landpachtvertrag: Kündigungsfristen und Ausgleich für den Pächter einplanen."],
131	    kommune: [0, "Kommunale oder kirchliche Fläche: Gremienbeschluss und ggf. Ausschreibung einplanen."],
132	  }[eigentum];
133	  if (eig) add(eig[0], eig[1]);
134	
135	  // --- Länderhinweis ----------------------------------------------
136	  if (land === "AT") add(0, "Österreich: Nötig ist eine Widmung als Grünland-Photovoltaik bzw. eine Zonierung nach Landesrecht – die Regeln unterscheiden sich je Bundesland.", "info");
137	  if (land === "CH") add(0, "Schweiz: Außerhalb der Bauzone braucht es Standortgebundenheit nach Raumplanungsrecht; große Freiflächenanlagen sind nur eingeschränkt möglich.", "info");
138	
139	  const summe = gruende.reduce((s, g) => s + g.punkte, punkte);
140	  const score = Math.round(clamp(Math.min(summe, deckel), 0, 100));
141	  const ampel = score >= 65 ? "gruen" : score >= 40 ? "gelb" : "rot";
142	
143	  // --- Kennzahlen --------------------------------------------------
144	  const kwh = kwp * region.ertrag;
145	  const p = PACHT.freiflaecheProHa;
146	  // Je besser die Fläche, desto weiter oben in der Spanne liegt die Pacht
147	  const lage = clamp((score - 30) / 60, 0, 1);
148	  const pachtMin = ha * (p.min + (p.mittel - p.min) * lage * 0.6);
149	  const pachtMax = ha * (p.mittel + (p.max - p.mittel) * lage);
150	  const faktor30 = summeIndex(PACHT.laufzeit, PACHT.indexierung);
151	
152	  const agriMoeglich = ["acker", "gruenland"].includes(nutzung);
153	  const agriKwp = (ha / BAUART.agriVertikal.haProMwp) * 1000; // vertikal-bifazial, konservativ
154	
155	  return {
156	    score,
157	    ampel,
158	    gruende: gruende.sort((a, b) => Math.abs(b.punkte) - Math.abs(a.punkte)),
159	    region,
160	    nutzbarHa,
161	    kwp,
162	    kwh,
163	    netzProKwp,
164	    pachtJahr: { min: pachtMin, max: pachtMax },
165	    pacht30: { min: pachtMin * faktor30, max: pachtMax * faktor30 },
166	    agri: agriMoeglich
167	      ? { kwp: agriKwp, pachtJahr: { min: ha * PACHT.agriProHa.min, max: ha * PACHT.agriProHa.max }, gapAnteil: AGRI.gapFoerderfaehig }
168	      : null,
169	    carport: nutzung === "parkplatz",
170	    schritte: naechsteSchritte({ ampel, land, eigentum, netz, nutzung }),
171	  };
172	}
