 40	export const STANDARD = {
 41	  mwp: 10,
 42	  anschlussQuote: 1,
 43	  km: 2,
 44	  ebene: "auto",
 45	  kapazitaet: "unbekannt",
 46	  speicherMw: 0,
 47	  speicherNetzbezug: false,
 48	  cluster: false,
 49	  land: "de",
 50	};
