 52	/** Spannweite der Kostenschätzung (Tiefbau, Querungen, Genehmigungen, Materialpreise) */
 53	export const SPANNE = { min: 0.8, max: 1.4 };
 54	/** Anteil gemeinsam genutzter Kosten (Trasse, Umspannwerk), die bei Clusterung mit einem Nachbarprojekt entfallen – eigene Annahme */
 55	export const CLUSTER_ANTEIL = 0.5;
 56	
 57	const ERTRAG_DE = Math.round(REGIONEN.filter((r) => r.land === "DE").reduce((s, r) => s + r.ertrag, 0) / REGIONEN.filter((r) => r.land === "DE").length);
 58	
 59	/** Energieverlust (Anteil) bei Anschlussleistung/Modulleistung – lineare Interpolation der Tabelle */
 60	export function abregelVerlust(quote) {
 61	  const t = N.abregelung;
 62	  if (quote >= t[0][0]) return 0;
 63	  for (let i = 1; i < t.length; i++) {
 64	    const [q1, v1] = t[i - 1];
 65	    const [q2, v2] = t[i];
 66	    if (quote >= q2) return v1 + ((q1 - quote) / (q1 - q2)) * (v2 - v1);
 67	  }
 68	  return t[t.length - 1][1];
 69	}
 70	
 71	export function ebeneFuer(anschlussMw) {
 72	  return anschlussMw <= N.grenzeMsMw ? "msLeitung" : anschlussMw <= N.grenzeUwMw ? "uwMs" : "hs";
 73	}
 74	
 75	/** Kosten (mittlerer Schätzwert) für eine gegebene Anschlussleistung */
 76	export function kosten(e, anschlussMw, ebene) {
 77	  const posten = [];
 78	  const kabelSysteme = Math.max(1, Math.ceil(anschlussMw / N.msSystemMw - 1e-9));
 79	  const kabelMs = e.km * 1000 * FREIFLAECHE.kabelProMeter * (1 + (kabelSysteme - 1) * N.zusatzSystemFaktor);
 80	  const teil = e.cluster ? 1 - CLUSTER_ANTEIL : 1;
 81	
 82	  posten.push({ id: "station", label: "Übergabe- und Trafostationen im Park", eur: e.mwp * FREIFLAECHE.netzanschlussFixProMwp, geteilt: false });
 83	  if (ebene === "msLeitung") {
 84	    posten.push({ id: "einschleifen", label: "Einschleifen in die MS-Leitung", eur: N.einschleifen, geteilt: false });
 85	    posten.push({ id: "kabel", label: `Kabeltrasse 20 kV (${kabelSysteme} ${kabelSysteme > 1 ? "Systeme" : "System"})`, eur: kabelMs * teil, geteilt: e.cluster });
 86	  } else if (ebene === "uwMs") {
 87	    posten.push({ id: "feld", label: `Schaltfeld${kabelSysteme > 1 ? "er" : ""} im Umspannwerk (${kabelSysteme})`, eur: N.uwFeld.mittel * kabelSysteme, geteilt: false });
 88	    posten.push({ id: "kabel", label: `Kabeltrasse 20 kV (${kabelSysteme} ${kabelSysteme > 1 ? "Systeme" : "System"})`, eur: kabelMs * teil, geteilt: e.cluster });
 89	  } else {
 90	    posten.push({ id: "uw", label: "Eigenes Umspannwerk 110/20 kV", eur: (N.kundenUwFix + N.kundenUwProMva * anschlussMw) * teil, geteilt: e.cluster });
 91	    posten.push({ id: "kabel", label: "Kabeltrasse 110 kV", eur: e.km * N.hsKabelProKm.mittel * teil, geteilt: e.cluster });
 92	  }
 93	  if (e.speicherMw > 0 && e.speicherNetzbezug) {
 94	    const satz = ebene === "hs" ? SPEICHER.bkzProKw.hs : SPEICHER.bkzProKw.ms;
 95	    posten.push({ id: "bkz", label: "Baukostenzuschuss für Netzbezug des Speichers", eur: e.speicherMw * 1000 * satz, geteilt: false });
 96	  }
 97	  const summe = posten.reduce((s, p) => s + p.eur, 0);
 98	  return { posten, summe, kabelSysteme };
 99	}
