101	export function rechneNetzanschluss(eingabe = {}) {
102	  const e = { ...STANDARD, ...eingabe };
103	  const anschlussMw = e.mwp * e.anschlussQuote;
104	  const vorschlag = ebeneFuer(anschlussMw);
105	  const ebene = e.ebene === "auto" ? vorschlag : e.ebene;
106	  const k = kosten(e, anschlussMw, ebene);
107	
108	  // Überbauung: Vergleich mit voller Anschlussleistung
109	  const voll = kosten(e, e.mwp, e.ebene === "auto" ? ebeneFuer(e.mwp) : ebene);
110	  const einsparung = Math.max(0, voll.summe - k.summe);
111	  const verlustRoh = abregelVerlust(e.anschlussQuote);
112	  const kappung = Math.max(0, e.mwp - anschlussMw);
113	  const speicherAuffang = kappung > 0 ? Math.min(1, e.speicherMw / kappung) * 0.8 : 0;
114	  const verlust = verlustRoh * (1 - speicherAuffang);
115	  const ertragKwh = e.mwp * 1000 * ERTRAG_DE;
116	  const verlustKwh = ertragKwh * verlust;
117	  const verlustEurJahr = (verlustKwh * ERLOESE.eegFreiflaecheCt) / 100;
118	  const bwFaktor20 = (1 - Math.pow(1.05, -20)) / 0.05; // Barwert 20 Jahre bei 5 %
119	  const verlustBarwert = verlustEurJahr * bwFaktor20;
120	
121	  // Zeitrahmen in Monaten ab vollständigem Netzanschlussbegehren
122	  const basis = { msLeitung: [9, 18], uwMs: [12, 30], hs: [24, 48] }[ebene];
123	  const plus = { frei: [0, 0], unbekannt: [0, 12], knapp: [24, 60] }[e.kapazitaet];
124	  const trasse = e.km > 5 ? [3, 9] : [0, 0];
125	  const monate = [basis[0] + plus[0] + trasse[0], basis[1] + plus[1] + trasse[1]];
126	
127	  const capexAnlage = e.mwp * 1000 * FREIFLAECHE.capexProKwp.mittel;
128	
129	  // Ampel: Kostenanteil an der Anlage und Kapazität
130	  const anteil = k.summe / capexAnlage;
131	  const ampel = e.kapazitaet === "knapp" || anteil > 0.3 ? "kritisch" : e.kapazitaet === "unbekannt" || anteil > 0.15 ? "pruefen" : "gut";
132	
133	  const risiken = [];
134	  if (e.kapazitaet === "knapp") risiken.push("Netzausbau durch den Netzbetreiber nötig – die Kosten trägt er (§ 17 EEG), die Zeit tragen Sie: oft mehrere Jahre bis zur Einspeisung.");
135	  if (e.kapazitaet === "unbekannt") risiken.push("Kapazität unbekannt: Die Netzverträglichkeitsprüfung kann einen weiter entfernten Verknüpfungspunkt ergeben – das ändert Kosten und Zeitplan erheblich.");
136	  if (e.km > 5) risiken.push(`Lange Trasse (${e.km.toLocaleString("de-DE")} km): Jedes Flurstück braucht eine Leitungsdienstbarkeit; Querungen von Straßen, Bahn und Gewässern verlängern Planung und Genehmigung.`);
137	  if (ebene === "hs") risiken.push("110-kV-Anschluss: eigenes Umspannwerk mit langen Lieferzeiten für Transformatoren und eigenem Genehmigungsverfahren.");
138	  if (anteil > 0.15) risiken.push(`Der Netzanschluss macht rund ${Math.round(anteil * 100)} % der Anlagenkosten aus – das drückt die Rendite spürbar.`);
139	  if (e.speicherMw > 0 && e.speicherNetzbezug) risiken.push("Speicher mit Netzbezug: Baukostenzuschuss (BGH, 15.07.2025) und Bezugsnetzentgelte einplanen; Befreiungen nach aktuellem Stand befristet.");
140	  if (e.anschlussQuote < 0.7 && e.speicherMw === 0) risiken.push("Starke Überbauung ohne Speicher: spürbare Abregelungsverluste – ein Speicher kann sie großteils auffangen.");
141	  if (risiken.length === 0) risiken.push("Keine auffälligen Risiken aus den Angaben – entscheidend ist die verbindliche Auskunft des Netzbetreibers.");
142	
143	  const tipps = [];
144	  if (e.land === "de") {
145	    tipps.push(`Netzanschlussbegehren früh und vollständig nach § 8 EEG stellen: Der Netzbetreiber muss unverzüglich einen Zeitplan nennen und spätestens nach ${N.pruefWochen} Wochen das Ergebnis der Netzverträglichkeitsprüfung samt Kostenvoranschlag vorlegen (§ 8 Abs. 5 und 6 EEG).`);
146	    tipps.push("Reservierung klären: Viele Netzbetreiber reservieren Kapazität nur befristet und verlangen Nachweise zum Projektfortschritt (etwa Flächensicherung, Aufstellungsbeschluss) – teils mit Reservierungsentgelt. Die Regeln unterscheiden sich je Netzbetreiber.");
147	  }
148	  if (e.land === "at") tipps.push("Österreich: Netzzugang beim Verteilnetzbetreiber beantragen; es fallen Netzzutritts- und ggf. Netzbereitstellungsentgelte an. Kapazitäten werden je Netzbereich veröffentlicht – früh prüfen.");
149	  if (e.land === "ch") tipps.push("Schweiz: Anschlussbedingungen des Verteilnetzbetreibers maßgeblich; notwendige Netzverstärkungen werden in der Regel über die Netzkosten (Swissgrid) getragen – vorab bestätigen lassen.");
150	  if (!e.cluster) tipps.push("Clusterung prüfen: Mit Nachbarprojekten eine gemeinsame Trasse oder ein gemeinsames Umspannwerk nutzen – das teilt Kosten und Planungsaufwand.");
151	  else tipps.push("Clusterung: Kostenaufteilung, Bauabfolge und Haftung bei Verzögerung eines Partners vertraglich regeln.");
152	  if (e.anschlussQuote >= 0.95) tipps.push("Überbauung erwägen: Mit 70–80 % Anschlussleistung je MWp gehen oft nur wenige Prozent Ertrag verloren; eine flexible Netzanschlussvereinbarung nach § 8a EEG kann Kapazität schneller verfügbar machen.");
153	  if (e.speicherMw === 0) tipps.push("Speicher am selben Anschluss (Co-Location) glättet die Einspeisespitze, fängt Abregelung auf und schafft zusätzliche Erlöse.");
154	  tipps.push("Leitungsrechte früh sichern: Dienstbarkeiten entlang der Trasse sind oft der längste Weg – parallel zum B-Plan-Verfahren beginnen.");
155	
156	  return {
157	    eingabe: e,
158	    anschlussMw,
159	    ebene,
160	    vorschlag,
161	    posten: k.posten,
162	    kabelSysteme: k.kabelSysteme,
163	    summe: k.summe,
164	    spanne: { min: k.summe * SPANNE.min, max: k.summe * SPANNE.max },
165	    proKwp: k.summe / (e.mwp * 1000),
166	    anteil,
167	    ampel,
168	    ueberbauung: { einsparung, verlust, verlustKwh, verlustEurJahr, verlustBarwert, lohnt: einsparung > verlustBarwert, speicherAuffang },
169	    monate,
170	    risiken,
171	    tipps,
172	  };
173	}
