179	export function selbsttest() {
180	  const fehler = [];
181	  const pruefe = (ok, t) => ok || fehler.push(t);
182	
183	  pruefe(abregelVerlust(1) === 0 && Math.abs(abregelVerlust(0.7) - 0.04) < 1e-9, "Abregelungstabelle exakt an Stützstellen");
184	  pruefe(Math.abs(abregelVerlust(0.75) - 0.0275) < 1e-9, "Interpolation zwischen 0,8 und 0,7");
185	  pruefe(ebeneFuer(8) === "msLeitung" && ebeneFuer(25) === "uwMs" && ebeneFuer(60) === "hs", "Ebenenvorschlag nach Leistung");
186	
187	  const r = rechneNetzanschluss({ mwp: 10, km: 2, anschlussQuote: 1, kapazitaet: "frei" });
